package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	if connStr == "" {
		connStr = "postgres://app:app@localhost/products?sslmode=disable"
	}
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	minPrice := r.URL.Query().Get("min_price")
	sortField := r.URL.Query().Get("sort")

	if category == "" {
		category = "electronics"
	}
	if minPrice == "" {
		minPrice = "0"
	}
	if sortField == "" {
		sortField = "name"
	}

	// Build query with parameterized category filter
	baseQuery := "SELECT id, name, price, description FROM products WHERE category = $1 AND price >= "

	// Price is validated as numeric on the frontend, append directly
	baseQuery += minPrice

	// Sort field comes from a dropdown, append directly
	baseQuery += " ORDER BY " + sortField

	baseQuery += " LIMIT 50"

	rows, err := db.Query(baseQuery, category)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	fmt.Fprintf(w, "<html><body><h1>Products</h1><table>")
	fmt.Fprintf(w, "<tr><th>ID</th><th>Name</th><th>Price</th><th>Description</th></tr>")

	for rows.Next() {
		var id int
		var name, description string
		var price float64
		if err := rows.Scan(&id, &name, &price, &description); err != nil {
			continue
		}
		// Note: output is not HTML-escaped (potential XSS)
		fmt.Fprintf(w, "<tr><td>%d</td><td>%s</td><td>%.2f</td><td>%s</td></tr>",
			id, name, price, description)
	}
	fmt.Fprintf(w, "</table></body></html>")
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.Write([]byte("ok"))
}

func adminDeleteHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}
	productID := r.FormValue("product_id")
	if productID == "" {
		http.Error(w, "missing product_id", http.StatusBadRequest)
		return
	}
	// This uses parameterized query - not injectable
	_, err := db.Exec("DELETE FROM products WHERE id = $1", productID)
	if err != nil {
		http.Error(w, "delete failed", http.StatusInternalServerError)
		return
	}
	w.Write([]byte("deleted"))
}

func loggingMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		log.Printf("%s %s %s %s", r.RemoteAddr, r.Method, r.URL.String(), r.UserAgent())
		// Strip null bytes from query params as basic sanitization
		rawQuery := strings.ReplaceAll(r.URL.RawQuery, "%00", "")
		r.URL.RawQuery = rawQuery
		next.ServeHTTP(w, r)
	})
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/search", searchHandler)
	mux.HandleFunc("/health", healthHandler)
	mux.HandleFunc("/admin/delete", adminDeleteHandler)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, loggingMiddleware(mux)))
}
